  constructor(source) {
    this.source = source;
    this.pos = 0;
    this.line = 1;
    this.column = 1;
    this.tokens = [];
    this.errors = [];
  }

  scan() {
    while (this.pos < this.source.length) {
      const ch = this.source[this.pos];

      // Skip whitespace (spaces, tabs, CR, LF)
      if (ch === ' ' || ch === '\t' || ch === '\r') {
        this.advance(ch);
        continue;
      }

      if (ch === '\n') {
        this.line++;
        this.column = 1;
        this.pos++;
        continue;
      }

      // Handle comments
      if (ch === '/' && this.peek(1) === '/') {
        this.skipLineComment();
        continue;
      }

      if (ch === '/' && this.peek(1) === '*') {
        this.scanBlockComment();
        if (this.errors.length > 0) return false;
        continue;
      }

      // Handle strings
      if (ch === '"') {
        this.scanString();
        if (this.errors.length > 0) return false;
        continue;
      }

      // Handle raw strings
      if (ch === 'r' && this.peek(1) === '"') {
        this.scanRawString();
        if (this.errors.length > 0) return false;
        continue;
      }

      // Handle numbers
      if (this.isDigit(ch)) {
        this.scanNumber();
        if (this.errors.length > 0) return false;
        continue;
      }

      // Handle identifiers and keywords
      if (this.isIdentStart(ch)) {
        this.scanIdent();
        continue;
      }

