 * Scanner for tokenizing source code.
 * Works on an array of code points so that astral characters count as one
 * column, as the specification requires.
 */

const KEYWORDS = new Set([
  'let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'
])

// Longest first: the two character operators must win over their prefixes.
const PUNCT_TOKENS = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.'
]

class ScanError extends Error {
  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

export class Scanner {
  constructor(source) {
    this.chars = Array.from(source)
    this.n = this.chars.length
    this.pos = 0
    this.line = 1
    this.column = 1
    this.tokens = []
    this.error = null
  }

  scan() {
    try {
      this.run()
    } catch (err) {
      if (!(err instanceof ScanError)) throw err
      this.error = { line: err.line, column: err.column, reason: err.reason }
      return false
    }
    return true
  }

  run() {
    while (this.pos < this.n) {
      const ch = this.peek(0)

      if (ch === ' ' || ch === '\t' || ch === '\r') {
        this.advance()
        continue
      }
      if (ch === '\n') {
        this.advance()
        continue
      }
      if (ch === '/' && this.peek(1) === '/') {
        this.skipLineComment()
        continue
      }
      if (ch === '/' && this.peek(1) === '*') {
        this.scanBlockComment()
        continue
      }
      if (ch === '"') {
        this.scanString()
        continue
      }
      if (ch === 'r' && this.peek(1) === '"') {
        this.scanRawString()
        continue
      }
      if (this.isDigit(ch)) {
        this.scanNumber()
        continue
      }
      if (this.isIdentStart(ch)) {
        this.scanIdent()
        continue
      }
      if (this.tryPunct()) continue

      this.fail(this.line, this.column, `unexpected character ${ch}`)
    }
  }

  fail(line, column, reason) {
    throw new ScanError(line, column, reason)
  }

  peek(offset = 0) {
    const ch = this.chars[this.pos + offset]
    return ch === undefined ? '' : ch
  }

  /** Consumes one code point, updating the line and the column. */
  advance() {
    const ch = this.chars[this.pos]
    this.pos++
    if (ch === '\n') {
      this.line++
      this.column = 1
    } else if (ch === '\t') {
      this.column = Math.floor((this.column - 1) / 4 + 1) * 4 + 1
    } else {
      this.column++
    }
  }

  advanceMany(count) {
    for (let i = 0; i < count; i++) this.advance()
  }

