  isBinDigit(ch) {
    return ch === '0' || ch === '1'
  }

  isOctDigit(ch) {
    return ch >= '0' && ch <= '7'
  }

  isIdentStart(ch) {
    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_'
