        if (isDigitOfClass(ch)) {
          this.advance()
          continue
        }
        if (ch === '_') {
          const before = this.peek(-1)
          const after = this.peek(1)
          if (!isDigitOfClass(before) || !isDigitOfClass(after)) bad(this.pos + 1)
          this.advance()
          continue
        }
        return
      }
    }
