/**
 * Scanner for tokenizing source code.
 * Handles all tokenization rules including position tracking,
 * different token types, comments, and error handling.
 */

const KEYWORDS = new Set([
  'let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'
]);

const PUNCT_TOKENS = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.'
];

export class Scanner {
  constructor(source) {
    this.source = source;
    this.pos = 0;
    this.line = 1;
    this.column = 1;
    this.tokens = [];
    this.errors = [];
  }

  scan() {
    while (this.pos < this.source.length) {
      const ch = this.source[this.pos];

      // Skip whitespace (spaces, tabs, CR, LF)
      if (ch === ' ' || ch === '\t' || ch === '\r') {
        this.advance(ch);
        continue;
      }

      if (ch === '\n') {
        this.line++;
        this.column = 1;
        this.pos++;
        continue;
      }

      // Handle comments
      if (ch === '/' && this.peek(1) === '/') {
        this.skipLineComment();
        continue;
      }

      if (ch === '/' && this.peek(1) === '*') {
        this.scanBlockComment();
        if (this.errors.length > 0) return false;
        continue;
      }

      // Handle strings
      if (ch === '"') {
        this.scanString();
        if (this.errors.length > 0) return false;
        continue;
      }

      // Handle raw strings
      if (ch === 'r' && this.peek(1) === '"') {
        this.scanRawString();
        if (this.errors.length > 0) return false;
        continue;
      }

      // Handle numbers
      if (this.isDigit(ch)) {
        this.scanNumber();
        if (this.errors.length > 0) return false;
        continue;
      }

      // Handle identifiers and keywords
      if (this.isIdentStart(ch)) {
        this.scanIdent();
        continue;
      }

      // Handle punctuation
      if (this.isPunctChar(ch)) {
        this.scanPunct();
        continue;
      }

      // Unexpected character
      this.errors.push({
        line: this.line,
        column: this.column,
        reason: `unexpected character ${ch}`
      });
      return false;
    }

    return this.errors.length === 0;
  }

  peek(offset = 0) {
    return this.source[this.pos + offset] || '';
  }

  advance(ch) {
    if (ch === '\t') {
      // Tab moves to next multiple of 4 plus 1
      this.column = Math.floor((this.column - 1 + 4) / 4) * 4 + 1;
    } else {
      this.column++;
    }
    this.pos++;
  }

  isDigit(ch) {
    return ch >= '0' && ch <= '9';
  }

  isHexDigit(ch) {
    return this.isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
  }

  isBinDigit(ch) {
    return ch === '0' || ch === '1';
  }

  isOctDigit(ch) {
    return ch >= '0' && ch <= '7';
  }

  isIdentStart(ch) {
    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_';
  }

  isIdentCont(ch) {
    return this.isIdentStart(ch) || this.isDigit(ch);
  }

  isPunctChar(ch) {
    return '=!<>+-*/%(){}[],.;'.includes(ch);
  }

  skipLineComment() {
    // Skip // and continue until line feed or EOF
    this.pos += 2;
    this.column += 2;

    while (this.pos < this.source.length && this.source[this.pos] !== '\n') {
      this.advance(this.source[this.pos]);
    }
  }

  scanBlockComment() {
    const startLine = this.line;
    const startCol = this.column;

    // Skip /*
    this.pos += 2;
    this.column += 2;

    let depth = 1;

    while (this.pos < this.source.length && depth > 0) {
      if (this.source[this.pos] === '/' && this.peek(1) === '*') {
        depth++;
        this.pos += 2;
        this.column += 2;
      } else if (this.source[this.pos] === '*' && this.peek(1) === '/') {
        depth--;
        this.pos += 2;
        this.column += 2;
      } else if (this.source[this.pos] === '\n') {
        this.line++;
        this.column = 1;
        this.pos++;
      } else {
        this.advance(this.source[this.pos]);
      }
    }

    if (depth > 0) {
      this.errors.push({
        line: startLine,
        column: startCol,
        reason: 'unterminated block comment'
      });
    }
  }

  scanString() {
    const startLine = this.line;
    const startCol = this.column;

    this.pos++; // Skip opening "
    this.column++;

    let value = '';

    while (this.pos < this.source.length) {
      const ch = this.source[this.pos];

      if (ch === '"') {
        this.pos++;
        this.column++;
        this.tokens.push({
          line: startLine,
          column: startCol,
          kind: 'string',
          body: JSON.stringify(value)
        });
        return;
      }

      if (ch === '\n') {
        this.errors.push({
          line: this.line,
          column: this.column,
          reason: 'newline in string'
        });
        return;
      }

      if (ch === '\\') {
        const escapeResult = this.parseEscape();
        if (escapeResult === null) {
          return; // Error was already added
        }
        value += escapeResult;
      } else {
        value += ch;
        this.advance(ch);
      }
    }

    this.errors.push({
      line: startLine,
      column: startCol,
      reason: 'unterminated string'
    });
  }

  parseEscape() {
    const startCol = this.column;
    this.pos++; // Skip backslash
    this.column++;

    if (this.pos >= this.source.length) {
      this.errors.push({
        line: this.line,
        column: startCol,
        reason: `invalid escape \\`
      });
      return null;
    }

    const ch = this.source[this.pos];
    this.pos++;
    this.column++;

    switch (ch) {
      case 'n': return '\n';
      case 't': return '\t';
      case 'r': return '\r';
      case '\\': return '\\';
      case '"': return '"';
      case '0': return '\0';
      case 'x': {
        // \xHH - exactly two hex digits
        if (!this.isHexDigit(this.peek(0)) || !this.isHexDigit(this.peek(1))) {
          this.errors.push({
            line: this.line,
            column: startCol,
            reason: `invalid escape \\x`
          });
          return null;
        }
        const hex = this.source.substr(this.pos, 2);
        this.pos += 2;
        this.column += 2;
        return String.fromCharCode(parseInt(hex, 16));
      }
      case 'u': {
        // \u{H...} - at least one hex digit
        if (this.peek(0) !== '{') {
          this.errors.push({
            line: this.line,
            column: startCol,
            reason: `invalid escape \\u`
          });
          return null;
        }
        this.pos++;
        this.column++;

        let hex = '';
        while (this.pos < this.source.length && this.source[this.pos] !== '}') {
          if (!this.isHexDigit(this.source[this.pos])) {
            this.errors.push({
              line: this.line,
              column: startCol,
              reason: `invalid escape \\u`
            });
            return null;
          }
          hex += this.source[this.pos];
          this.pos++;
          this.column++;
        }

        if (hex.length === 0 || this.pos >= this.source.length) {
          this.errors.push({
            line: this.line,
            column: startCol,
            reason: `invalid escape \\u`
          });
          return null;
        }

        const codePoint = parseInt(hex, 16);
        if (codePoint > 0x10FFFF) {
          this.errors.push({
            line: this.line,
            column: startCol,
            reason: `invalid escape \\u`
          });
          return null;
        }

        this.pos++; // Skip closing }
        this.column++;
        return String.fromCodePoint(codePoint);
      }
      default:
        this.errors.push({
          line: this.line,
          column: startCol,
          reason: `invalid escape \\${ch}`
        });
        return null;
    }
  }

  scanRawString() {
    const startLine = this.line;
    const startCol = this.column;

    this.pos += 2; // Skip r"
    this.column += 2;

    let value = '';

    while (this.pos < this.source.length) {
      const ch = this.source[this.pos];

      if (ch === '"') {
        this.pos++;
        this.column++;
        this.tokens.push({
          line: startLine,
          column: startCol,
          kind: 'rawstring',
          body: JSON.stringify(value)
        });
        return;
      }

      value += ch;

      if (ch === '\n') {
        this.line++;
        this.column = 1;
        this.pos++;
      } else {
        this.advance(ch);
      }
    }

    this.errors.push({
      line: startLine,
      column: startCol,
      reason: 'unterminated string'
    });
  }

  scanNumber() {
    const startLine = this.line;
    const startCol = this.column;
    const startPos = this.pos;

    if (this.source[this.pos] === '0') {
      const next = this.peek(1);

      if (next === 'x' || next === 'X') {
        // Hexadecimal
        this.pos += 2;
        this.column += 2;

        if (!this.isHexDigit(this.peek(0))) {
          // No digit after prefix
          const text = this.source.substring(startPos, this.pos);
          this.errors.push({
            line: startLine,
            column: startCol,
            reason: `invalid number ${text}`
          });
          return;
        }

        while (this.isHexDigit(this.peek(0)) || this.peek(0) === '_') {
          if (this.peek(0) === '_') {
            // Check underscore is between two digits
            if (!this.isHexDigit(this.peek(-1)) || !this.isHexDigit(this.peek(1))) {
              const text = this.source.substring(startPos, this.pos + 1);
              this.errors.push({
                line: startLine,
                column: startCol,
                reason: `invalid number ${text}`
              });
              return;
            }
          }
          this.advance(this.peek(0));
        }

        // Check for invalid trailing character
        const ch = this.peek(0);
        if (this.isIdentStart(ch) || this.isDigit(ch) || ch === '_') {
          const text = this.source.substring(startPos, this.pos + 1);
          this.errors.push({
            line: startLine,
            column: startCol,
            reason: `invalid number ${text}`
          });
          return;
        }

        this.tokens.push({
          line: startLine,
          column: startCol,
          kind: 'number',
          body: this.source.substring(startPos, this.pos)
        });
        return;
      }

      if (next === 'b' || next === 'B') {
        // Binary
        this.pos += 2;
        this.column += 2;

        if (!this.isBinDigit(this.peek(0))) {
          const text = this.source.substring(startPos, this.pos);
          this.errors.push({
            line: startLine,
            column: startCol,
            reason: `invalid number ${text}`
          });
          return;
        }

        while (this.isBinDigit(this.peek(0)) || this.peek(0) === '_') {
          if (this.peek(0) === '_') {
            if (!this.isBinDigit(this.peek(-1)) || !this.isBinDigit(this.peek(1))) {
              const text = this.source.substring(startPos, this.pos + 1);
              this.errors.push({
                line: startLine,
                column: startCol,
                reason: `invalid number ${text}`
              });
              return;
            }
          }
          this.advance(this.peek(0));
        }

        const ch = this.peek(0);
        if (this.isIdentStart(ch) || this.isDigit(ch) || ch === '_') {
          const text = this.source.substring(startPos, this.pos + 1);
          this.errors.push({
            line: startLine,
            column: startCol,
            reason: `invalid number ${text}`
          });
          return;
        }

        this.tokens.push({
          line: startLine,
          column: startCol,
          kind: 'number',
          body: this.source.substring(startPos, this.pos)
        });
        return;
      }

      if (next === 'o' || next === 'O') {
        // Octal
        this.pos += 2;
        this.column += 2;

        if (!this.isOctDigit(this.peek(0))) {
          const text = this.source.substring(startPos, this.pos);
          this.errors.push({
            line: startLine,
            column: startCol,
            reason: `invalid number ${text}`
          });
          return;
        }

        while (this.isOctDigit(this.peek(0)) || this.peek(0) === '_') {
          if (this.peek(0) === '_') {
            if (!this.isOctDigit(this.peek(-1)) || !this.isOctDigit(this.peek(1))) {
              const text = this.source.substring(startPos, this.pos + 1);
              this.errors.push({
                line: startLine,
                column: startCol,
                reason: `invalid number ${text}`
              });
              return;
            }
          }
          this.advance(this.peek(0));
        }

        const ch = this.peek(0);
        if (this.isIdentStart(ch) || this.isDigit(ch) || ch === '_') {
          const text = this.source.substring(startPos, this.pos + 1);
          this.errors.push({
            line: startLine,
            column: startCol,
            reason: `invalid number ${text}`
          });
          return;
        }

        this.tokens.push({
          line: startLine,
          column: startCol,
          kind: 'number',
          body: this.source.substring(startPos, this.pos)
        });
        return;
      }
    }

    // Decimal number
    while (this.isDigit(this.peek(0)) || this.peek(0) === '_') {
      if (this.peek(0) === '_') {
        if (!this.isDigit(this.peek(-1)) || !this.isDigit(this.peek(1))) {
          const text = this.source.substring(startPos, this.pos + 1);
          this.errors.push({
            line: startLine,
            column: startCol,
            reason: `invalid number ${text}`
          });
          return;
        }
      }
      this.advance(this.peek(0));
    }

    // Optional decimal point
    if (this.peek(0) === '.' && this.isDigit(this.peek(1))) {
      this.advance('.');
      while (this.isDigit(this.peek(0)) || this.peek(0) === '_') {
        if (this.peek(0) === '_') {
          if (!this.isDigit(this.peek(-1)) || !this.isDigit(this.peek(1))) {
            const text = this.source.substring(startPos, this.pos + 1);
            this.errors.push({
              line: startLine,
              column: startCol,
              reason: `invalid number ${text}`
            });
            return;
          }
        }
        this.advance(this.peek(0));
      }
    }

    // Optional exponent
    if ((this.peek(0) === 'e' || this.peek(0) === 'E') && 
        (this.isDigit(this.peek(1)) || 
         ((this.peek(1) === '+' || this.peek(1) === '-') && this.isDigit(this.peek(2))))) {
      this.advance(this.peek(0));
      if (this.peek(0) === '+' || this.peek(0) === '-') {
        this.advance(this.peek(0));
      }
      while (this.isDigit(this.peek(0)) || this.peek(0) === '_') {
        if (this.peek(0) === '_') {
          if (!this.isDigit(this.peek(-1)) || !this.isDigit(this.peek(1))) {
            const text = this.source.substring(startPos, this.pos + 1);
            this.errors.push({
              line: startLine,
              column: startCol,
              reason: `invalid number ${text}`
            });
            return;
          }
        }
        this.advance(this.peek(0));
      }
    }

    // Check for invalid trailing character
    const ch = this.peek(0);
    if (this.isIdentStart(ch) || this.isDigit(ch) || ch === '_') {
      const text = this.source.substring(startPos, this.pos + 1);
      this.errors.push({
        line: startLine,
        column: startCol,
        reason: `invalid number ${text}`
      });
      return;
    }

    this.tokens.push({
      line: startLine,
      column: startCol,
      kind: 'number',
      body: this.source.substring(startPos, this.pos)
    });
  }

  scanIdent() {
    const startLine = this.line;
    const startCol = this.column;
    const startPos = this.pos;

    while (this.isIdentCont(this.peek(0))) {
      this.advance(this.peek(0));
    }

    const text = this.source.substring(startPos, this.pos);
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident';

    this.tokens.push({
      line: startLine,
      column: startCol,
      kind,
      body: text
    });
  }

  scanPunct() {
    const startLine = this.line;
    const startCol = this.column;

    // Try longest match first
    for (const punct of PUNCT_TOKENS) {
      if (this.source.substr(this.pos, punct.length) === punct) {
        for (let i = 0; i < punct.length; i++) {
          this.advance(this.peek(0));
        }
        this.tokens.push({
          line: startLine,
          column: startCol,
          kind: 'punct',
          body: punct
        });
        return;
      }
    }
  }

  getTokens() {
    return this.tokens;
  }

  getError() {
    return this.errors[0] || null;
  }
}

