/**
 * Scanner for tokenizing source code.
 * Works on an array of code points so that astral characters count as one
 * column, as the specification requires.
 */

const KEYWORDS = new Set([
  'let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'
])

// Longest first: the two character operators must win over their prefixes.
const PUNCT_TOKENS = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.'
]

class ScanError extends Error {
  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

export class Scanner {
  constructor(source) {
    this.chars = Array.from(source)
    this.n = this.chars.length
    this.pos = 0
    this.line = 1
    this.column = 1
    this.tokens = []
    this.error = null
  }

  scan() {
    try {
      this.run()
    } catch (err) {
      if (!(err instanceof ScanError)) throw err
      this.error = { line: err.line, column: err.column, reason: err.reason }
      return false
    }
    return true
  }

  run() {
    while (this.pos < this.n) {
      const ch = this.peek(0)

      if (ch === ' ' || ch === '\t' || ch === '\r') {
        this.advance()
        continue
      }
      if (ch === '\n') {
        this.advance()
        continue
      }
      if (ch === '/' && this.peek(1) === '/') {
        this.skipLineComment()
        continue
      }
      if (ch === '/' && this.peek(1) === '*') {
        this.scanBlockComment()
        continue
      }
      if (ch === '"') {
        this.scanString()
        continue
      }
      if (ch === 'r' && this.peek(1) === '"') {
        this.scanRawString()
        continue
      }
      if (this.isDigit(ch)) {
        this.scanNumber()
        continue
      }
      if (this.isIdentStart(ch)) {
        this.scanIdent()
        continue
      }
      if (this.tryPunct()) continue

      this.fail(this.line, this.column, `unexpected character ${ch}`)
    }
  }

  fail(line, column, reason) {
    throw new ScanError(line, column, reason)
  }

  peek(offset = 0) {
    const ch = this.chars[this.pos + offset]
    return ch === undefined ? '' : ch
  }

  /** Consumes one code point, updating the line and the column. */
  advance() {
    const ch = this.chars[this.pos]
    this.pos++
    if (ch === '\n') {
      this.line++
      this.column = 1
    } else if (ch === '\t') {
      this.column = Math.floor((this.column - 1) / 4 + 1) * 4 + 1
    } else {
      this.column++
    }
  }

  advanceMany(count) {
    for (let i = 0; i < count; i++) this.advance()
  }

  slice(from, to) {
    return this.chars.slice(from, to).join('')
  }

  isDigit(ch) {
    return ch >= '0' && ch <= '9'
  }

  isHexDigit(ch) {
    return this.isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F')
  }

  isBinDigit(ch) {
    return ch === '0' || ch === '1'
  }

  isOctDigit(ch) {
    return ch >= '0' && ch <= '7'
  }

  isIdentStart(ch) {
    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_'
  }

  isIdentCont(ch) {
    return this.isIdentStart(ch) || this.isDigit(ch)
  }

  skipLineComment() {
    this.advanceMany(2)
    while (this.pos < this.n && this.peek(0) !== '\n') this.advance()
  }

  scanBlockComment() {
    const line = this.line
    const column = this.column
    this.advanceMany(2)
    let depth = 1
    while (this.pos < this.n) {
      if (this.peek(0) === '/' && this.peek(1) === '*') {
        depth++
        this.advanceMany(2)
      } else if (this.peek(0) === '*' && this.peek(1) === '/') {
        depth--
        this.advanceMany(2)
        if (depth === 0) return
      } else {
        this.advance()
      }
    }
    this.fail(line, column, 'unterminated block comment')
  }

  scanString() {
    const line = this.line
    const column = this.column
    this.advance() // opening quote
    let value = ''

    while (this.pos < this.n) {
      const ch = this.peek(0)
      if (ch === '"') {
        this.advance()
        this.tokens.push({ line, column, kind: 'string', body: JSON.stringify(value) })
        return
      }
      if (ch === '\n') {
        this.fail(this.line, this.column, 'newline in string')
      }
      if (ch === '\\') {
        value += this.readEscape(line, column)
      } else {
        value += ch
        this.advance()
      }
    }

    this.fail(line, column, 'unterminated string')
  }

  /** Reads one escape sequence, the backslash included, and returns its value. */
  readEscape(stringLine, stringColumn) {
    const line = this.line
    const column = this.column
    this.advance() // backslash

    if (this.pos >= this.n) {
      // The input ended inside the string, so it never closed.
      this.fail(stringLine, stringColumn, 'unterminated string')
    }

    const ch = this.peek(0)
    const invalid = () => this.fail(line, column, `invalid escape \\${ch}`)

    switch (ch) {
      case 'n': this.advance(); return '\n'
      case 't': this.advance(); return '\t'
      case 'r': this.advance(); return '\r'
      case '\\': this.advance(); return '\\'
      case '"': this.advance(); return '"'
      case '0': this.advance(); return '\0'
      case 'x': {
        if (!this.isHexDigit(this.peek(1)) || !this.isHexDigit(this.peek(2))) invalid()
        const hex = this.slice(this.pos + 1, this.pos + 3)
        this.advanceMany(3)
        return String.fromCharCode(parseInt(hex, 16))
      }
      case 'u': {
        if (this.peek(1) !== '{') invalid()
        let i = this.pos + 2
        let hex = ''
        while (i < this.n && this.isHexDigit(this.chars[i])) {
          hex += this.chars[i]
          i++
        }
        if (hex.length === 0 || this.chars[i] !== '}') invalid()
        const code = parseInt(hex, 16)
        if (!(code <= 0x10ffff)) invalid()
        this.advanceMany(i + 1 - this.pos)
        return String.fromCodePoint(code)
      }
      default:
        return invalid()
    }
  }

  scanRawString() {
    const line = this.line
    const column = this.column
    this.advanceMany(2) // r and the quote
    const start = this.pos

    while (this.pos < this.n) {
      if (this.peek(0) === '"') {
        const value = this.slice(start, this.pos)
        this.advance()
        this.tokens.push({ line, column, kind: 'rawstring', body: JSON.stringify(value) })
        return
      }
      this.advance()
    }

    this.fail(line, column, 'unterminated string')
  }

  scanNumber() {
    const line = this.line
    const column = this.column
    const start = this.pos

    const bad = (through) => {
      this.fail(line, column, `invalid number ${this.slice(start, through)}`)
    }
    // A run of digits of one class, with underscores only between two digits.
    const digits = (isDigitOfClass) => {
      while (true) {
        const ch = this.peek(0)
        if (isDigitOfClass(ch)) {
          this.advance()
          continue
        }
        if (ch === '_') {
          const before = this.peek(-1)
          const after = this.peek(1)
          if (!isDigitOfClass(before) || !isDigitOfClass(after)) bad(this.pos + 1)
          this.advance()
          continue
        }
        return
      }
    }
    // Nothing of the number's own syntax may run straight into a word.
    const checkTrailer = () => {
      const ch = this.peek(0)
      if (this.isIdentCont(ch)) bad(this.pos + 1)
    }

    if (this.peek(0) === '0') {
      const marker = this.peek(1)
      let isDigitOfClass = null
      if (marker === 'x' || marker === 'X') isDigitOfClass = (c) => this.isHexDigit(c)
      else if (marker === 'b' || marker === 'B') isDigitOfClass = (c) => this.isBinDigit(c)
      else if (marker === 'o' || marker === 'O') isDigitOfClass = (c) => this.isOctDigit(c)

      if (isDigitOfClass) {
        this.advanceMany(2)
        if (!isDigitOfClass(this.peek(0))) {
          // A prefix with no digit after it, plus whatever sat there.
          bad(this.isIdentCont(this.peek(0)) ? this.pos + 1 : this.pos)
        }
        digits(isDigitOfClass)
        checkTrailer()
        this.tokens.push({ line, column, kind: 'number', body: this.slice(start, this.pos) })
        return
      }
    }

    const isDec = (c) => this.isDigit(c)
    digits(isDec)

    if (this.peek(0) === '.' && this.isDigit(this.peek(1))) {
      this.advance()
      digits(isDec)
    }

    const marker = this.peek(0)
    if (marker === 'e' || marker === 'E') {
      const next = this.peek(1)
      if (this.isDigit(next)) {
        this.advance()
        digits(isDec)
      } else if ((next === '+' || next === '-') && this.isDigit(this.peek(2))) {
        this.advanceMany(2)
        digits(isDec)
      }
    }

    checkTrailer()
    this.tokens.push({ line, column, kind: 'number', body: this.slice(start, this.pos) })
  }

  scanIdent() {
    const line = this.line
    const column = this.column
    const start = this.pos
    while (this.isIdentCont(this.peek(0))) this.advance()
    const text = this.slice(start, this.pos)
    this.tokens.push({ line, column, kind: KEYWORDS.has(text) ? 'keyword' : 'ident', body: text })
  }

  tryPunct() {
    const line = this.line
    const column = this.column
    for (const punct of PUNCT_TOKENS) {
      if (this.slice(this.pos, this.pos + punct.length) === punct) {
        this.advanceMany(punct.length)
        this.tokens.push({ line, column, kind: 'punct', body: punct })
        return true
      }
    }
    return false
  }

  getTokens() {
    return this.tokens
  }

  getError() {
    return this.error
  }
}

