import { Scanner } from './scanner.js'

async function main() {
  const args = process.argv.slice(2)

  // Validate arguments
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read stdin
  let input = ''
  for await (const chunk of process.stdin) {
    input += chunk
  }

  // Scan the input
  const scanner = new Scanner(input)
  const success = scanner.scan()

  if (!success) {
    const error = scanner.getError()
    process.stderr.write(`error: ${error.line}:${error.column}: ${error.reason}\n`)
    process.exit(2)
  }

  // Output results
  if (mode === 'tokens') {
    const tokens = scanner.getTokens()
    for (const token of tokens) {
      process.stdout.write(`${token.line}:${token.column} ${token.kind} ${token.body}\n`)
    }
  } else {
    // stats mode
    const tokens = scanner.getTokens()
    const counts = {
      ident: 0,
      keyword: 0,
      number: 0,
      punct: 0,
      rawstring: 0,
      string: 0
    }

    for (const token of tokens) {
      counts[token.kind]++
    }

    process.stdout.write(`ident ${counts.ident}\n`)
    process.stdout.write(`keyword ${counts.keyword}\n`)
    process.stdout.write(`number ${counts.number}\n`)
    process.stdout.write(`punct ${counts.punct}\n`)
    process.stdout.write(`rawstring ${counts.rawstring}\n`)
    process.stdout.write(`string ${counts.string}\n`)
    process.stdout.write(`total ${tokens.length}\n`)
  }

  process.exit(0)
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
})

