  if (mode === 'tokens') {
    for (const token of tokens) {
      out += `${token.line}:${token.column} ${token.kind} ${token.body}\n`
    }
  } else {
    const counts = new Map(KINDS.map((kind) => [kind, 0]))
    for (const token of tokens) counts.set(token.kind, counts.get(token.kind) + 1)
    for (const kind of KINDS) out += `${kind} ${counts.get(kind)}\n`
    out += `total ${tokens.length}\n`
  }
  if (out.length > 0) process.stdout.write(out)
}

main().catch((err) => {
  fail(err && err.message ? err.message : String(err))
})
